const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Los Angeles area geometry
  var la = ee.Geometry.Polygon([[
    [-118.7, 33.6], [-118.7, 34.3], 
    [-117.9, 34.3], [-117.9, 33.6], [-118.7, 33.6]
  ]]);

  // Function to get NO2 data for a given year
  function getNO2Data(year) {
    var startDate = year + '-10-01';
    var endDate = year + '-10-24'; // Oct 1-23 inclusive

    var collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(la)
      .select('tropospheric_NO2_column_number_density');

    return collection;
  }

  // Get collections for all three years
  var col2018 = getNO2Data('2018');
  var col2019 = getNO2Data('2019');
  var col2021 = getNO2Data('2021');

  // Check collection sizes
  var size2018 = col2018.size().getInfo();
  var size2019 = col2019.size().getInfo();
  var size2021 = col2021.size().getInfo();

  console.log('2018 Images: ' + size2018);
  console.log('2019 Images: ' + size2019);
  console.log('2021 Images: ' + size2021);

  // If any collection is empty, output C1
  if (size2018 === 0 || size2019 === 0 || size2021 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean NO2 for each period
  function calculateMean(collection) {
    var composite = collection.mean();
    var stats = composite.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: la,
      scale: 1000,
      maxPixels: 1e9
    });
    return stats;
  }

  var stats2018 = calculateMean(col2018);
  var stats2019 = calculateMean(col2019);
  var stats2021 = calculateMean(col2021);

  var mean2018 = stats2018.get('tropospheric_NO2_column_number_density').getInfo();
  var count2018 = stats2018.get('tropospheric_NO2_column_number_density_count').getInfo();
  var mean2019 = stats2019.get('tropospheric_NO2_column_number_density').getInfo();
  var count2019 = stats2019.get('tropospheric_NO2_column_number_density_count').getInfo();
  var mean2021 = stats2021.get('tropospheric_NO2_column_number_density').getInfo();
  var count2021 = stats2021.get('tropospheric_NO2_column_number_density_count').getInfo();

  console.log('2018 Mean NO2: ' + mean2018.toFixed(6) + ' (Pixels: ' + count2018 + ')');
  console.log('2019 Mean NO2: ' + mean2019.toFixed(6) + ' (Pixels: ' + count2019 + ')');
  console.log('2021 Mean NO2: ' + mean2021.toFixed(6) + ' (Pixels: ' + count2021 + ')');

  // Check for no valid pixels
  if (count2018 === 0 || count2019 === 0 || count2021 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures
  if (mean2018 === null || mean2019 === null || mean2021 === null ||
      isNaN(mean2018) || isNaN(mean2019) || isNaN(mean2021)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Validate NO2 values are reasonable (typical range for urban areas)
  if (mean2018 < 0 || mean2019 < 0 || mean2021 < 0 || 
      mean2018 > 0.001 || mean2019 > 0.001 || mean2021 > 0.001) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if 2021 is lower than both 2018 and 2019
  if (mean2021 < mean2018 && mean2021 < mean2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
